using System.ComponentModel.DataAnnotations;

namespace ShipmentTracker.Data;

public class ShipmentEntity
{
    public int Id { get; set; }

    [MaxLength(20)]
    public string TrackingNumber { get; set; } = string.Empty;

    [MaxLength(200)]
    public string Origin { get; set; } = string.Empty;

    [MaxLength(200)]
    public string Destination { get; set; } = string.Empty;

    public int Status { get; set; }

    public DateTime CreatedAtUtc { get; set; }
    public DateTime? EstimatedDeliveryUtc { get; set; }

    [MaxLength(200)]
    public string RecipientName { get; set; } = string.Empty;

    [MaxLength(200)]
    public string RecipientEmail { get; set; } = string.Empty;

    [MaxLength(500)]
    public string? Notes { get; set; }
}

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ServerShipmentService(ApplicationDbContext db) : Client.Services.IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await db.Shipments
            .OrderByDescending(s => s.CreatedAtUtc)
            .Select(s => ToModel(s))
            .ToListAsync();
    }

    public async Task<Shipment?> GetByTrackingNumberAsync(string trackingNumber)
    {
        var entity = await db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return entity is null ? null : ToModel(entity);
    }

    public async Task<Shipment?> UpdateStatusAsync(int id, ShipmentStatus status)
    {
        var entity = await db.Shipments.FindAsync(id);
        if (entity is null) return null;

        entity.Status = (int)status;
        await db.SaveChangesAsync();
        return ToModel(entity);
    }

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        var entity = new ShipmentEntity
        {
            TrackingNumber = GenerateTrackingNumber(),
            Origin = shipment.Origin,
            Destination = shipment.Destination,
            Status = (int)ShipmentStatus.Pending,
            CreatedAtUtc = DateTime.UtcNow,
            EstimatedDeliveryUtc = shipment.EstimatedDeliveryUtc,
            RecipientName = shipment.RecipientName,
