namespace ShipmentTracker.Data;

public static class SeedData
{
    public static void Initialize(ApplicationDbContext db)
    {
        if (db.Shipments.Any())
            return;

        var now = DateTime.UtcNow;

        db.Shipments.AddRange(
            new ShipmentEntity
            {
                TrackingNumber = "SHP-20260601-100001",
                Origin = "New York, USA",
                Destination = "London, UK",
                Status = 2, // InTransit
                CreatedAtUtc = now.AddDays(-3),
                EstimatedDeliveryUtc = now.AddDays(2),
                RecipientName = "James Wilson",
                RecipientEmail = "jwilson@example.com"
            },
            new ShipmentEntity
